'use strict';
const $=id=>document.getElementById(id),t=OrionI18n.t;
const orders=[[0,1,2],[0,2,1],[1,0,2],[1,2,0],[2,0,1],[2,1,0]];
const journeys=[[0,3,6],[7,4,1],[2,5,0],[6,1,4],[3,0,7],[5,2,6]];
const names=[['Dew','露珠'],['Reed','蘆葦'],['Pebble','卵石'],['Comet','彗星'],['Fern','蕨葉'],['Willow','柳枝'],['Clover','三葉草'],['Meteor','流星']];
const questions=[['Are the antenna tips rounded knobs?','觸角末端有圓球嗎？'],['Are there four spots on the back?','背上有四個斑點嗎？'],['Is the body long and narrow?','身體是修長的嗎？']];
const labels=[[['Plain tips','普通末端'],['Rounded tips','圓球末端']],[['No spots','沒有斑點'],['Four spots','四個斑點']],[['Round body','圓身體'],['Long body','長身體']]];
let variant=OrionProgress.variant('keys'),observedVariant=variant,observedTarget=OrionProgress.read().hashTarget,stage=0,path=[],solved=false,hintDepth=0,hintOpen=false,state='ready',saveFailed=false;
function features(id){return [id>>2&1,id>>1&1,id&1];}
function challenge(v=variant,s=stage){return {target:journeys[v][s],order:orders[(v+s)%6]};}
function candidates(q=challenge(),p=path){return names.map((_,i)=>i).filter(i=>p.every((a,n)=>features(i)[q.order[n]]===a));}
function choose(value){if(solved||path.length===3||![0,1].includes(value))return;path.push(value);state='ready';render();if(path.length===3)$('check').focus();else $('choices').querySelector('button')?.focus();}
function resetTrial(){path=[];solved=false;hintDepth=0;hintOpen=false;state='ready';saveFailed=false;$('notes').open=false;render();}
function resetMission(v=OrionProgress.variant('keys')){variant=v;stage=0;resetTrial();}
function check(){if(solved)return;if(path.length!==3)state='incomplete';else if(candidates()[0]!==challenge().target)state='wrong';else{solved=true;state='success';if(stage===2)saveFailed=!OrionProgress.earn('insight');}render();if(solved&&stage<2)$('next').focus();}
function beetle(id){const [knobs,spots,long]=features(id),rx=long?21:34,ry=long?46:34;return `<svg viewBox="0 0 140 160" aria-hidden="true"><g fill="none" stroke="#c6ba87" stroke-width="5" stroke-linecap="round"><path d="M55 70L30 58L19 67M53 87L25 87L14 101M54 105L33 118L26 137M85 70L110 58L121 67M87 87L115 87L126 101M86 105L107 118L114 137M61 42L47 22L40 16M79 42L93 22L100 16"/></g>${knobs?'<g fill="#ffe4a0"><circle cx="40" cy="16" r="7"/><circle cx="100" cy="16" r="7"/></g>':''}<ellipse cx="70" cy="91" rx="${rx}" ry="${ry}" fill="#478e80" stroke="#e1c988" stroke-width="3"/><path d="M70 ${91-ry}V${91+ry}" stroke="#183e39" stroke-width="3"/><ellipse cx="70" cy="49" rx="19" ry="17" fill="#194c49" stroke="#d9c18d" stroke-width="2"/><g fill="#fff2bd"><circle cx="62" cy="45" r="3"/><circle cx="78" cy="45" r="3"/>${spots?[[-10,79],[10,79],[-10,103],[10,103]].map(([x,y])=>`<circle cx="${70+x}" cy="${y}" r="5"/>`).join(''):''}</g></svg>`;}
function description(id){return features(id).map((a,i)=>t(...labels[i][a])).join(' · ');}
function hints(){return [t('Compare the visitor with both choices. Use what you can see, not a guess about what it eats or where it lives.','把訪客與兩個選項比較。使用看得見的特徵，不要猜牠吃甚麼或住在哪裏。'),t('The faded journal pictures no longer match your chosen path. Each fork divides the remaining group into two.','筆記中變暗的圖像不再符合你選的路。每個分支把剩下的群組分成兩部分。'),t('If the final picture differs from the visitor, go back. Check antenna tips, back spots and body shape carefully.','若最後的圖像與訪客不同，就退回去，仔細檢查觸角末端、背上斑點和身形。')];}
function render(){const q=challenge(),left=candidates(),complete=solved&&stage===2,p=stage+Number(solved);window.OrionDiscovery?.update(complete);document.title=t('The Moonwing Archive · Orion','月翼檔案館 · Orion');$('stageTitle').textContent=t(`Visitor ${stage+1} · Set ${variant+1}`,`第 ${stage+1} 位訪客 · 題組 ${variant+1}`);$('sceneStatus').textContent=t(`Archive seals · ${p} / 3`,`檔案館封印 · ${p} / 3`);$('seals').textContent=Array.from({length:3},(_,i)=>i<p?'◆':'◇').join(' ');$('scene').classList.toggle('complete',complete);
$('visitor').innerHTML=beetle(q.target);$('visitor').setAttribute('role','img');$('visitor').setAttribute('aria-label',t('Visitor: ','訪客：')+description(q.target));$('observation').textContent=description(q.target);
$('question').textContent=path.length<3?t(...questions[q.order[path.length]]):t('You reached a name. Compare both pictures.','你找到了一個名字，比較兩幅圖像。');$('choices').innerHTML=path.length<3?[0,1].map(a=>`<button data-choice="${a}">${t(...labels[q.order[path.length]][a])}</button>`).join(''):'';
$('catalog').innerHTML=names.map((name,i)=>`<div class="entry ${left.includes(i)?'possible':'excluded'}" aria-label="${t(...name)}: ${description(i)} — ${left.includes(i)?t('matches path','符合路線'):t('excluded by path','被路線排除')}">${beetle(i)}<span>${t(...name)}${left.includes(i)?'':' ×'}</span></div>`).join('');$('remaining').textContent=t(`${left.length} of 8 match your path`, `8 種中有 ${left.length} 種符合你的路線`);$('trail').innerHTML=path.map((a,i)=>`<li>${t(...labels[q.order[i]][a])}</li>`).join('');
$('feedback').textContent=state==='success'?t(`It is ${t(...names[q.target])}! Your observations match the journal.`,`是${t(...names[q.target])}！你的觀察與筆記吻合。`):state==='wrong'?t('That path finds a different beetle. Compare the pictures and go back to change a choice.','這條路找到另一隻甲蟲。比較圖像，退回去更改選項。'):state==='incomplete'?t('Follow all three forks before checking the identity.','先走完三個分支，再檢查身分。'):path.length===3?t(`Your path finds ${t(...names[left[0]])}. Does it match the visitor?`,`這條路找到${t(...names[left[0]])}。與訪客相同嗎？`):t('Watch the possible identities narrow as you choose.','作出選擇，觀察可能的身分逐步減少。');
$('check').hidden=solved;$('check').disabled=path.length<3;$('back').disabled=solved||!path.length;$('retry').hidden=solved;$('next').hidden=!solved||stage===2;$('reward').hidden=!complete;$('notes').hidden=!complete;$('hint').disabled=solved;$('hint').setAttribute('aria-label',t('Reveal the next clue','顯示下一個提示'));$('hint').setAttribute('aria-expanded',String(hintOpen));$('hints').hidden=!hintOpen;$('hints').innerHTML=hints().slice(0,hintDepth).map(h=>`<li>${h}</li>`).join('')+`<li class="close-clues"><button data-close>${t('Close clues','關閉提示')}</button></li>`;$('retrySave').hidden=!saveFailed;$('saveStatus').textContent=saveFailed?t('Sigil earned, but saving failed. Try saving again.','已獲得符印，但儲存失敗。請再次儲存。'):OrionProgress.has('insight')?t('Insight Sigil saved in your collection.','明察符印已存入收藏。'):'';}
$('hints').onclick=e=>{if(e.target.closest('button[data-close]')){hintOpen=false;render();$('hint').focus();}};window.addEventListener('keydown',e=>{if(e.key==='Escape'&&hintOpen){hintOpen=false;render();$('hint').focus();}});$('choices').onclick=e=>{const b=e.target.closest('button[data-choice]');if(b)choose(Number(b.dataset.choice));};$('back').onclick=()=>{if(solved||!path.length)return;path.pop();state='ready';render();};$('check').onclick=check;$('retry').onclick=()=>{if(!solved)resetTrial();};$('next').onclick=()=>{if(!solved||stage===2)return;stage++;resetTrial();};$('hint').onclick=()=>{hintDepth=Math.min(3,hintDepth+1);hintOpen=true;render();};$('replay').onclick=()=>{const v=OrionProgress.nextVariant('keys',variant);observedVariant=OrionProgress.variant('keys');resetMission(v);};$('retrySave').onclick=()=>{if(!solved||stage!==2)return;saveFailed=!OrionProgress.earn('insight');render();};function syncProgress(){const v=OrionProgress.variant('keys'),h=OrionProgress.read().hashTarget,changed=v!==observedVariant||h!==observedTarget;observedVariant=v;observedTarget=h;if(changed||solved&&stage===2&&!OrionProgress.has('insight')&&!saveFailed)resetMission();else render();}window.addEventListener('orion-language',render);window.addEventListener('storage',e=>{if(e.key==='orion-expedition-progress-v1'||e.key===null)syncProgress();});window.addEventListener('pageshow',syncProgress);resetMission();OrionI18n.apply();
